package main

import (
	"fmt"
	"math"
)

const (
	eps = 1e-6
	PI  = math.Pi
)

type Point struct {
	x, y float64
}

func (p Point) add(o Point) Point {
	return Point{p.x + o.x, p.y + o.y}
}

func (p Point) sub(o Point) Point {
	return Point{p.x - o.x, p.y - o.y}
}

func (p Point) scale(v float64) Point {
	return Point{p.x * v, p.y * v}
}

func (p Point) div(v float64) Point {
	return p.scale(1.0 / v)
}

func (p Point) rot90() Point {
	return Point{-p.y, p.x}
}

func (p Point) mod() float64 {
	return math.Sqrt(p.x*p.x + p.y*p.y)
}

func (p Point) mod2() float64 {
	return p.x*p.x + p.y*p.y
}

func (p Point) dot(o Point) float64 {
	return p.x*o.x + p.y*o.y
}

func (p Point) cross(o Point) float64 {
	return p.x*o.y - p.y*o.x
}

func (p Point) unit() Point {
	return p.div(p.mod())
}

func (p Point) rotate(alph float64) Point {
	sa, ca := math.Sincos(alph)
	return Point{p.x*ca - p.y*sa, p.x*sa + p.y*ca}
}

func (p Point) shadowOnLine(a, b Point) Point {
	ab := b.sub(a)
	ap := p.sub(a)
	alph := ab.unit().scale(ap.dot(ab) / ab.mod())
	return a.add(alph)
}

func lineCrossCircle(a, b, o Point, r float64) []Point {
	t := o.shadowOnLine(a, b)
	ot := t.sub(o)
	if ot.mod()-r > eps {
		return nil
	}
	if math.Abs(ot.mod()-r) < eps {
		return []Point{t}
	}
	lr := math.Sqrt(r*r - ot.mod2())
	ta := t.add(a.sub(t).unit().scale(lr))
	tb := t.add(b.sub(t).unit().scale(lr))
	return []Point{ta, tb}
}

func pointTangentCircle(p, o Point, r float64) []Point {
	x2 := p.sub(o).mod2()
	d2 := x2 - r*r
	if d2 < -eps {
		return nil
	}
	if r <= eps {
		return []Point{o, o}
	}
	d2 = math.Max(d2, 0)
	q1 := o.add(p.sub(o).scale(r*r / x2))
	q2 := p.sub(o).rot90().scale(-r * math.Sqrt(d2) / x2)
	return []Point{q1.sub(q2), q1.add(q2)}
}

func pOnSeg(p, a, b Point) bool {
	if math.Abs(a.sub(b).cross(p.sub(a))) > eps {
		return false
	}
	if math.Min(a.x, b.x) > p.x || p.x > math.Max(a.x, b.x) {
		return false
	}
	if math.Min(a.y, b.y) > p.y || p.y > math.Max(a.y, b.y) {
		return false
	}
	return true
}

func pDisLine(p, a, b Point) float64 {
	return p.shadowOnLine(a, b).sub(p).mod()
}

func corner2V(a, b Point) float64 {
	return math.Abs(math.Acos(a.dot(b) / a.mod() / b.mod()))
}

func check(t float64, p, s Point, vp, vs, r, sita float64) bool {
	lenOr := p.mod()
	e := Point{lenOr * math.Cos(sita + t*vp/lenOr), lenOr * math.Sin(sita + t*vp/lenOr)}
	ccp := lineCrossCircle(s, e, Point{0, 0}, r)
	if len(ccp) != 2 || (!pOnSeg(ccp[0], s, e) && !pOnSeg(ccp[1], s, e)) {
		return vs*t > e.sub(s).mod()
	}
	ttp1 := pointTangentCircle(s, Point{0, 0}, r)
	if pDisLine(ttp1[0], s, e) > pDisLine(ttp1[1], s, e) {
		ttp1[0], ttp1[1] = ttp1[1], ttp1[0]
	}
	l1 := s.sub(ttp1[0]).mod()
	ttp2 := pointTangentCircle(e, Point{0, 0}, r)
	if pDisLine(ttp2[0], s, e) > pDisLine(ttp2[1], s, e) {
		ttp2[0], ttp2[1] = ttp2[1], ttp2[0]
	}
	l2 := e.sub(ttp2[0]).mod()
	alph := corner2V(ttp1[0], ttp2[0])
	return l1 + l2 + alph*r < vs*t
}

func main() {
	var p, s Point
	var vp, vs, r float64
	for {
		_, err := fmt.Scan(&p.x, &p.y, &vp, &s.x, &s.y, &vs, &r)
		if err != nil {
			break
		}
		sita := math.Acos(p.x / p.mod())
		if p.y < 0 {
			sita = -sita
		}
		left, right := 0.0, 1e10
		for math.Abs(left-right) > 1e-12 {
			mid := (left + right) * 0.5
			if check(mid, p, s, vp, vs, r, sita) {
				right = mid
			} else {
				left = mid
			}
		}
		fmt.Printf("%.9f\n", left)
	}
}
