func (p Point) mod2() float64 {
	return p.x*p.x + p.y*p.y
}

func dot(a, b Point) float64 {
	return a.x*b.x + a.y*b.y
}

func cross(a, b Point) float64 {
	return a.x*b.y - a.y*b.x
}

func vecUnit(a Point) Point {
	m := a.mod()
	if m < 1e-12 {
		return Point{0, 0}
	}
	return a.div(m)
}

func vRotate(v Point, alph float64) Point {
	sa, ca := math.Sin(alph), math.Cos(alph)
	return Point{v.x*ca - v.y*sa, v.x*sa + v.y*ca}
}

func pRotate(p, o Point, alph float64) Point {
	return o.add(vRotate(p.sub(o), alph))
}

func shadowPOnLine(p, a, b Point) Point {
	ab := b.sub(a)
	ap := p.sub(a)
	u := vecUnit(ab)
	return a.add(u.mul(dot(ab, ap) / ab.mod()))
}

func lineCrossCircle(a, b, o Point, r float64) []Point {
	t := shadowPOnLine(o, a, b)
	ot := t.sub(o)
	if ot.mod()-r > 1e-6 {
		return nil
	}
	if math.Abs(ot.mod()-r) < 1e-6 {
		return []Point{t}
	}
	lr := math.Sqrt(r*r - ot.mod2())
	ta := t.add(vecUnit(a.sub(t)).mul(lr))
	tb := t.add(vecUnit(b.sub(t)).mul(lr))
	return []Point{ta, tb}
}

