	d2 = math.Max(d2, 0)
	q1 := o.add(p.sub(o).mul(r*r / x2))
	q2 := p.sub(o).rot90().mul(-r * math.Sqrt(d2) / x2)
	return []Point{q1.sub(q2), q1.add(q2)}
}

func pOnSeg(p, a, b Point) bool {
	if math.Abs(cross(b.sub(a), p.sub(a))) > 1e-6 {
		return false
	}
	if math.Min(a.x, b.x)-1e-6 > p.x || p.x > math.Max(a.x, b.x)+1e-6 {
		return false
	}
	if math.Min(a.y, b.y)-1e-6 > p.y || p.y > math.Max(a.y, b.y)+1e-6 {
		return false
	}
	return true
}

func pDisLine(p, a, b Point) float64 {
	return shadowPOnLine(p, a, b).sub(p).mod()
}

func corner2V(a, b Point) float64 {
	return math.Abs(math.Acos(dot(a, b) / a.mod() / b.mod()))
}

func check(t, vp, vs, r float64, p, s Point, sita float64) bool {
	lenOr := p.mod()
	e := Point{lenOr * math.Cos(sita+t*vp/lenOr), lenOr * math.Sin(sita+t*vp/lenOr)}
