	return p.mul(1.0 / s)
}

func (p Point) mod() float64 {
	return math.Sqrt(p.x*p.x + p.y*p.y)
}

func (p Point) mod2() float64 {
	return p.x*p.x + p.y*p.y
}

func (p Point) dot(o Point) float64 {
	return p.x*o.x + p.y*o.y
}

func (p Point) cross(o Point) float64 {
	return p.x*o.y - p.y*o.x
}

func (p Point) unit() Point {
	return p.div(p.mod())
}

func (p Point) rotate(alpha float64) Point {
	sa, ca := math.Sincos(alpha)
	return Point{p.x*ca - p.y*sa, p.x*sa + p.y*ca}
}

func (p Point) rotateAround(o Point, alpha float64) Point {
	return o.add(p.sub(o).rotate(alpha))
}

func (p Point) perpendicular() Point {
	return p.rotate(math.Pi / 2)
}

func (p Point) shadowOnLine(a, b Point) Point {
	ab := b.sub(a)
	ap := p.sub(a)
	unitAb := ab.unit()
	projLen := ab.dot(ap) / ab.mod()
	return a.add(unitAb.mul(projLen))
}

func (p Point) distanceToLine(a, b Point) float64 {
	return p.sub(p.shadowOnLine(a, b)).mod()
}

func lineCrossCircle(a, b, o Point, r float64) []Point {
	t := o.shadowOnLine(a, b)
	ot := t.sub(o)
	d := ot.mod()
	if d-r > 1e-6 {
		return nil
	}
	if math.Abs(d-r) < 1e-6 {
		return []Point{t}
